from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType

# 15 vertices, 28 labels (0 to 27)
# 27 edges, 27 differences (1 to 27)

V = 15
L = 28
E = 27
D = 27

edges = []
for g in range(5):
    edges.append((g*3 + 0, g*3 + 1))
    edges.append((g*3 + 1, g*3 + 2))
    edges.append((g*3 + 0, g*3 + 2))

for g in range(4):
    edges.append((g*3 + 0, (g+1)*3 + 0))
    edges.append((g*3 + 1, (g+1)*3 + 1))
    edges.append((g*3 + 2, (g+1)*3 + 2))

def var_x(v, l):
    return v * L + l + 1

def var_y(e, d):
    return V * L + e * D + (d - 1) + 1

solver = Glucose4()

# Each vertex has exactly one label
for v in range(V):
    solver.append_formula(CardEnc.equals(lits=[var_x(v, l) for l in range(L)], bound=1, vpool=None).clauses)

# Each label is used at most once
for l in range(L):
    solver.append_formula(CardEnc.atmost(lits=[var_x(v, l) for v in range(V)], bound=1, vpool=None).clauses)

# Each edge has exactly one difference
for e in range(E):
    solver.append_formula(CardEnc.equals(lits=[var_y(e, d) for d in range(1, D+1)], bound=1, vpool=None).clauses)

# Each difference is used exactly once
for d in range(1, D+1):
    solver.append_formula(CardEnc.equals(lits=[var_y(e, d) for e in range(E)], bound=1, vpool=None).clauses)

# Link x and y
for e, (u, v) in enumerate(edges):
    for l1 in range(L):
        for l2 in range(L):
            if l1 != l2:
                d = abs(l1 - l2)
                # x_{u, l1} and x_{v, l2} -> y_{e, d}
                solver.add_clause([-var_x(u, l1), -var_x(v, l2), var_y(e, d)])

# Symmetry breaking
# V[0] < V[1] < V[2]
for l1 in range(L):
    for l2 in range(l1+1):
        solver.add_clause([-var_x(0, l1), -var_x(1, l2)])
        solver.add_clause([-var_x(1, l1), -var_x(2, l2)])

# V[0] < V[12]
for l1 in range(L):
    for l2 in range(l1+1):
        solver.add_clause([-var_x(0, l1), -var_x(12, l2)])

# Graceful complement
for l in range(14, L):
    solver.add_clause([-var_x(0, l)])

print("Solving...")
if solver.solve():
    model = solver.get_model()
    labels = [-1] * V
    for v in range(V):
        for l in range(L):
            if model[var_x(v, l) - 1] > 0:
                labels[v] = l
    print("SAT")
    print(labels)
else:
    print("UNSAT")

